def agg(rows, prefix, keys=("recall@1", "recall@5", "recall@10", "mrr")):
    out = {}
    for name in ("tfidf", "emb", "ppr", "hybrid"):
        col = f"{prefix}_{name}"
        vals = [r[col] for r in rows if col in r and "error" not in r]
        if not vals:
            continue
        out[name] = {k: (sum(v[k] for v in vals) / len(vals)) for k in keys}
        out[name]["n"] = len(vals)
    return out


