                    node_file[n["id"]] = fp
            tf_fn = tfidf_rank(t["problem_statement"], fn_docs)
            hyb_fn = rrf_fuse([tf_fn, emb_node, ppr_node])
            gold_nodes = {nid for nid in fn_docs
                          if (node_file[nid], nid.split(".")[-1]) in gold_fn}
